mapper.select:
SELECT tab.* FROM ( SELECT ln.*, nvl(ifnull2(finance_plan_id, (SELECT 'Y' FROM dual WHERE EXISTS (SELECT 1 FROM cap_financing_plan WHERE plan_id = ln.finance_plan_id AND confirm_status != 'CANCEL')), 'N'), 'N') ref_flag, (SELECT MAX(ccc.full_write_off_date) FROM con_contract cc,con_contract_cashflow ccc WHERE cc.contract_id=ccc.contract_id AND ccc.cf_item=0 AND cc.plan_ln_id=ln.plan_line_id) last_investment_date, hd.plan_name, hd.plan_number, hd.approve_date, hd.approve_status, hd.plan_status, hd.data_class, hd.apply_investment_amount_sum, ( SELECT sys.description FROM sys_user sys WHERE sys.USER_ID = hd.user_id ) AS user_name, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = hd.unit_id) as unit_name, pp.project_number project_id_n, pp.project_name, pp.approval_amount credit_amount, pp.credit_plan, pp.payment_condition, pp.manage_condition, v1.meaning execute_status_desc, v2.meaning new_or_stock_n, (select currency_name from fnd_currency fc,prj_quotation pq where currency_code = pq.currency and pq.source_document_category = 'PRJ_PROJECT' and pq.source_document_id = pp.project_id) currency_name, (select description from hls_document_status where document_category = 'PRJ_PROJECT' and status_code = pp.project_status) project_status_n, (SELECT description FROM hls_document_type WHERE document_category = 'PRJ_PROJECT' AND business_type = pp.business_type AND enabled_flag = 'Y') business_type_n, (SELECT MIN(pc.due_date) FROM prj_quotation_cashflow pc, prj_quotation pq WHERE pc.quotation_id = pq.quotation_id AND pq.source_document_id = pp.project_id AND pq.source_document_category = 'PRJ_PROJECT' AND pq.data_class = 'PRJ_PROJECT_INVEST' ) lease_start_date, (SELECT MAX(pc.due_date) FROM prj_quotation_cashflow pc, prj_quotation pq WHERE pc.quotation_id = pq.quotation_id AND pq.source_document_id = pp.project_id AND pq.source_document_category = 'PRJ_PROJECT' AND pq.data_class = 'PRJ_PROJECT_INVEST' ) lease_end_date, (SELECT lease_item_amount FROM prj_quotation WHERE source_document_id = pp.project_id AND source_document_category = 'PRJ_PROJECT' AND data_class = 'PRJ_PROJECT_INVEST') finance_amount, (SELECT wm_concat(hbm.bp_name) FROM hls_bp_master hbm, prj_project_bp pb WHERE hbm.bp_id = pb.bp_id AND pb.project_id = pp.project_id AND pb.bp_categroy = 'PRJ_PROJECT' AND pb.bp_type = 'TENANT') seller_or_tenant, (SELECT wm_concat(hbm.bp_name ) FROM hls_bp_master hbm, prj_project_bp pb WHERE hbm.bp_id = pb.bp_id AND pb.project_id = pp.project_id AND pb.bp_categroy = 'PRJ_PROJECT' AND pb.bp_type = 'TENANT_SEC') buyer_or_tenant_sec, (SELECT lease_item_amount FROM prj_quotation WHERE source_document_id = pp.project_id AND source_document_category = 'PRJ_PROJECT' AND data_class = 'PRJ_PROJECT_INVEST') lease_item_amount FROM prj_project pp, cap_capital_invest_plan_hd hd, cap_capital_invest_plan_ln ln LEFT JOIN (SELECT vb.* FROM sys_code_b b, sys_code_value_b vb WHERE b.CODE_ID = vb.CODE_ID AND b.code = 'CAP.EXECUTE_STATUS') v1 ON v1.value = ln.execute_status LEFT JOIN (SELECT vb.* FROM sys_code_b b, sys_code_value_b vb WHERE b.CODE_ID = vb.CODE_ID AND b.code = 'CAP.NEW_OR_STOCK') v2 ON v2.value = ln.new_or_stock WHERE pp.project_id = ln.project_id AND ln.plan_head_id = hd.plan_head_id AND ln.company_id = pp.company_id) tab where 1=1
and tab.data_class = #{dataClass}
and tab.data_type = #{dataType}
and tab.company_id = #{request.companyId}
and tab.company_id = #{companyId}
and tab.plan_head_id = #{planHeadId}
and tab.execute_status != #{executeStatus}
and tab.execute_status not in ('EXECUTED','CANCEL') and tab.data_class = 'NORMAL' AND NOT EXISTS (select plan_id from cap_financing_plan where confirm_status != 'CANCEL' AND plan_id = tab.finance_plan_id)
and tab.plan_line_id = #{planLineId}
and tab.project_id = (select ref_project_id from prj_project where project_id = (select project_id from con_contract where contract_id = #{projectId}))
and tab.project_name like concat('%',concat(#{projectName},'%'))
and tab.plan_name like concat('%',concat(#{planName},'%'))
and tab.finance_plan_id = #{financePlanId}
and tab.approve_status = #{approveStatus}
and ((tab.plan_name like concat('%',concat(#{planInfo},'%')) or (tab.plan_number like concat('%',concat(#{planInfo},'%')))) and tab.approve_status = 'APPROVED'
and tab.execute_status in
#{item}
and tab.applyInvestmentAmount >= #{applyAmountFrom}
and tab.applyInvestmentAmount <= #{applyAmountTo}
and tab.actualInvestmentAmount >= #{actualAmountFrom}
and tab.actualInvestmentAmount <= #{actualAmountTo}
and tab.unit_name like concat('%',concat(#{unitName},'%'))
and tab.user_name like concat('%',concat(#{userName},'%'))
and tab.pay_date >= #{payDateFrom}
and tab.pay_date <= #{payDateTo}
and tab.last_investment_date >= #{actualPayDateFrom}
and tab.last_investment_date <= #{actualPayDateTo}
